const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerPoint = ee.Geometry.Point(140.878144, 27.245974);
  const bufferRadiusKm = 2; // 2 km radius
  const roi = centerPoint.buffer(bufferRadiusKm * 1000); // Buffer in meters
  const startDate = '2013-12-08';
  const endDate = '2013-12-09'; // Only looking for this specific day

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
    .filterDate(startDate, endDate)
    .filterBounds(roi);

  const initialImageCount = await collection.size().getInfo();
  console.log(`Initial Landsat 8 images found: ${initialImageCount}`);

  if (initialImageCount === 0) {
    console.log("No Landsat 8 images found for the specified date and location.");
    console.log("C1");
    return;
  }

  // Get the first image (should be only one for a specific day)
  const image = ee.Image(collection.first());

  // Cloud masking function for Landsat 8 SR
  function maskL8sr(image) {
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Get the pixel QA band.
    const qa = image.select('pixel_qa');
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['B4', 'B3', 'B2', 'B5', 'B6', 'B7']); // Select surface reflectance bands
  }

  const maskedImage = maskL8sr(image).clip(roi);

  // Check valid pixels after masking and clipping (using a visible band like B4)
  const bandToCount = 'B4';
  const scale = 30; // Landsat native resolution
  const validPixels = await maskedImage.select(bandToCount)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    })
    .get(bandToCount)
    .getInfo();

  console.log(`Valid pixels after cloud mask and clip: ${validPixels}`);

  if (validPixels === 0) {
    console.log("No valid pixels remain after cloud masking and clipping.");
    console.log("C2");
    return;
  }

  // 3. Processing: Identify land (potential islands)
  // Use NDWI to differentiate water from land. NDWI = (Green - NIR) / (Green + NIR)
  // Water generally has positive NDWI values, land has negative or near-zero.
  const ndwi = maskedImage.normalizedDifference(['B3', 'B5']).rename('NDWI'); // B3=Green, B5=NIR

  // Classify land (NDWI < 0) as potential island pixels.
  // Using a threshold of 0 for NDWI is common to separate water (positive) from non-water (negative/zero).
  const land = ndwi.lt(0).selfMask().rename('land');

  // Perform connected components analysis on the land pixels
  // Label contiguous groups of land pixels
  const connectedComponents = land.connectedComponents({
    connectedness: 8, // Diagonal and cardinal connections
    maxSize: 1000 // Max number of pixels in a component (arbitrary, adjust if needed)
  });

  // Count the number of unique connected components (islands)
  const islandCount = await connectedComponents.reduceRegion({
    reducer: ee.Reducer.countDistinct(connectedComponents.bandNames()),
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  })
    .values()
    .get(0) // Get the first (and only) value
    .getInfo();

  // 4. Validation & Final Answer
  // The reduceRegion might return null if no land pixels were found.
  if (islandCount === null || isNaN(islandCount)) {
    console.log("Could not determine island count. Calculation failed.");
    console.log("C3");
    return;
  }

  console.log(`Number of distinct land components (potential islands): ${islandCount}`);

  if (islandCount === 2) {
    console.log("A"); // Yes, there were two isolated islands
  } else {
    console.log("B"); // No, there were not two isolated islands
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
